import React, { useContext, useEffect, useRef, useState } from "react";
import { CartContext } from "../context/cartContext";
import { useTranslation } from "gatsby-plugin-react-i18next";

declare global {
  interface Window {
    paypal: any;
  }
}

interface PayPalActions {
  order: {
    create: (data: Record<string, unknown>) => Promise<string>;
    capture: () => Promise<PayPalOrderDetails>;
  };
}

interface PayPalOrderDetails {
  payer: {
    name: {
      given_name: string;
    };
  };
}

interface PayPalButtonProps {
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  onTransactionComplete: (
    orderDetails: string,
    totalAmount: string,
    customerPhone: string,
    customerName: string,
    customerEmail: string
  ) => Promise<void>;
}

const PayPalButton: React.FC<PayPalButtonProps> = ({
  customerName,
  customerEmail,
  customerPhone,
  onTransactionComplete,
}) => {
  const cartContext = useContext(CartContext);
  const { cart } = cartContext || { cart: [] };
  const total = cart
    .reduce((sum, item) => sum + item.price * item.quantity, 0)
    .toFixed(2);

  const paypalRef = useRef<HTMLDivElement | null>(null);
  const [sdkReady, setSdkReady] = useState(false);
  const { t } = useTranslation();

  useEffect(() => {
    const addPayPalScript = async () => {
      if (window.paypal) {
        setSdkReady(true);
        return;
      }

      const script = document.createElement("script");
      script.src =
        "https://www.paypal.com/sdk/js?client-id=ATQKMs5AduJ5C1Y0yoHaWJbOP4nZi79jUO8SO2OC6RHquloo4FUVOrmhxqkwPgxFaZg-l374QM-ZPBb9&currency=CAD";
      script.async = true;
      script.onload = () => setSdkReady(true);
      script.onerror = () => console.error("Error to load the PayPal SDK");
      document.body.appendChild(script);
    };

    addPayPalScript();

    return () => {
      if (paypalRef.current) {
        paypalRef.current.innerHTML = "";
      }
    };
  }, []);

  useEffect(() => {
    if (sdkReady && paypalRef.current) {
      paypalRef.current.innerHTML = "";

      try {
        window.paypal
          .Buttons({
            createOrder: async (_data: unknown, actions: PayPalActions) => {
              try {
                return await actions.order.create({
                  purchase_units: [
                    {
                      amount: {
                        currency_code: "CAD",
                        value: total,
                      },
                      description: "Purchase in Succulente Sculpture",
                    },
                  ],
                });
              } catch (error) {
                console.error("Error to create order:", error);
                return "";
              }
            },
            onApprove: async (_data: unknown, actions: PayPalActions) => {
              try {
                const details = await actions.order.capture(); 
                // console.log("Payment captured successfully:", details);

                const orderDetails = cart
                  .map(
                    (item) =>
                      `${item.name} | ${t("cart.quantity")}: ${item.quantity} | ${t("cart.price")}: ${(item.price * item.quantity).toFixed(2)} $`
                  )
                  .join("\n");

                await onTransactionComplete(
                  orderDetails,
                  total,
                  customerName,
                  customerEmail,
                  customerPhone
                );
              } catch (error) {
                console.error("Error to capture payment:", error);
              }
            },
            onError: (err: unknown) => console.error("Error in PayPal:", err),
          })
          .render(paypalRef.current);
      } catch (error) {
        console.error("Error to render PayPal:", error);
      }
    }
  }, [sdkReady, total]);

  return <div ref={paypalRef} id="paypal-button-container"></div>;
};

export default PayPalButton;
